func enrichAll(ctx context.Context, ids []int64) []Profile {
	out := make(chan Profile)

	for _, id := range ids {
		go func(id int64) {
			p, err := fetchProfile(id) // ~50 ms RPC
			if err != nil {
				return
			}
			out <- p
		}(id)
	}

	res := make([]Profile, 0, len(ids))
	for range ids {
		select {
		case p := <-out:
			res = append(res, p)
		case <-time.After(2 * time.Second):
			return res
		}
	}
	return res
}
